#!/bin/sh
# Generated by forge. SessionStart: <= 20 lines of repository context.
# this script's directory, absolute (builtins)
case $0 in */*) dir=${0%/*} ;; *) dir=. ;; esac
case $dir in /*) ;; *) dir=$PWD/$dir ;; esac
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
IFS='
'

# the generated checks and the engine modules they use (forge apply writes them next to this script)
. "$dir/checks.sh"

branch=$(git branch --show-current 2>/dev/null)
[ -n "$branch" ] || branch="(detached $(git rev-parse --short HEAD 2>/dev/null))"
# the changed files, counted and listed with builtins (status columns and rename sources cut)
status=$(git status --porcelain --untracked-files=all 2>/dev/null)
n=0
list=''
set -f
for _ss_f in $status; do
  n=$((n + 1))
  _ss_f=${_ss_f#???}
  [ "$n" -gt 10 ] || list="$list
  ${_ss_f##* -> }"
done
set +f
printf 'forge: branch %s, %s changed files\n' "$branch" "$n"
[ -z "$list" ] || printf '%s\n' "${list#?}"
head=$(git log -5 --format='%h %s' 2>/dev/null)
if [ -n "$head" ]; then
  printf 'forge: last commits\n'
  set -f
  for _ss_c in $head; do printf '  %.72s\n' "$_ss_c"; done
  set +f
fi
printf 'forge: packs @@PACKS@@\n'

# snapshots of Bash commands that never finished, older than a day (bash-snapshot.sh keeps the 50 newest)
forge_state_dir && bash_cleanup age

# the types engines the rules use start now, in the background, so the first edit
# does not wait for them (§15.3); this session is registered with them
if [ -n "$FORGE_TYPES_LANGS" ] && forge_state_dir; then
  for _ss_l in $FORGE_TYPES_LANGS; do
    ( forge_types_up "$_ss_l" ) < /dev/null > /dev/null 2>&1 &
  done
fi

missing=$(forge_missing_tools)
state=$FORGE_STATE/missing-tools
if [ -n "$missing" ]; then
  if [ "$missing" != "$(forge_cat "$state" 2>/dev/null)" ]; then
    printf 'forge: missing tools (checks using them are skipped): %s\n' "$missing"
    forge_state_dir && printf '%s\n' "$missing" > "$state"
  fi
elif [ -e "$state" ]; then
  rm -f "$state"
fi

# the project's Python environment (§9.1): said when none of the candidates has the
# project's declared dependencies installed, once until it changes
state=$FORGE_STATE/python-env
pyenv=''
if [ ! -x .venv/bin/python ] && [ ! -x .venv/bin/python3 ]; then
  forge_py_deps
  if [ -n "$FORGE_FACT" ] && forge_py_env; then
    case $FORGE_PY_DEPS in
      "0 "*)
        _ss_c=''
        for _ss_l in $FORGE_PY_CHECKED; do _ss_n=${_ss_l#* }; _ss_c="${_ss_c:+$_ss_c, }${_ss_l%% *} ${_ss_n% *}/${_ss_n#* }"; done
        pyenv="no Python environment has the project's ${FORGE_PY_DEPS#0 } declared dependencies installed (checked: $_ss_c); the checks use $FORGE_PY. Install them there, or activate the project's environment (VIRTUAL_ENV)" ;;
    esac
  fi
fi
if [ -n "$pyenv" ]; then
  if [ "$pyenv" != "$(forge_cat "$state" 2>/dev/null)" ]; then
    printf 'forge: %s\n' "$pyenv"
    forge_state_dir && printf '%s\n' "$pyenv" > "$state"
  fi
elif [ -e "$state" ]; then
  rm -f "$state"
fi

# what the installed tool versions cannot do (§16.3), once until it changes
report=$(forge_tool_report)
state=$FORGE_STATE/tool-report
if [ -n "$report" ]; then
  if [ "$report" != "$(forge_cat "$state" 2>/dev/null)" ]; then
    printf 'forge: tool versions (what they cannot do is not enforced):\n'
    # the first 4 lines, each cut at 400 characters (cut -c only for a longer one: it knows UTF-8)
    _ss_k=0
    set -f
    for _ss_r in $report; do
      _ss_k=$((_ss_k + 1))
      [ "$_ss_k" -le 4 ] || break
      if [ "${#_ss_r}" -le 400 ]; then printf '  %s\n' "$_ss_r"; else printf '  %s\n' "$(printf '%s\n' "$_ss_r" | cut -c 1-400)"; fi
    done
    set +f
    forge_state_dir && printf '%s\n' "$report" > "$state"
  fi
elif [ -e "$state" ]; then
  rm -f "$state"
fi
exit 0
